package com.gigu.engagement.domain.policy;import com.gigu.engagement.domain.valueobject.ProjectStatus;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class ProjectStatusPolicyTest {    private final ProjectStatusPolicy policy = new ProjectStatusPolicy();    @Test    void projectStatusPolicyAllowsOnlyValidBusinessFlow() {        assertAll(            () -> assertTrue(policy.canTransition(ProjectStatus.PENDING, ProjectStatus.IN_PROGRESS)),            () -> assertTrue(policy.canTransition(ProjectStatus.PENDING, ProjectStatus.CANCELLED)),            () -> assertTrue(policy.canTransition(ProjectStatus.IN_PROGRESS, ProjectStatus.DELIVERED)),            () -> assertTrue(policy.canTransition(ProjectStatus.IN_PROGRESS, ProjectStatus.CANCELLED)),            () -> assertTrue(policy.canTransition(ProjectStatus.DELIVERED, ProjectStatus.FINISHED)),            () -> assertFalse(policy.canTransition(ProjectStatus.FINISHED, ProjectStatus.IN_PROGRESS)),            () -> assertFalse(policy.canTransition(ProjectStatus.FINISHED, ProjectStatus.CANCELLED)),            () -> assertFalse(policy.canTransition(ProjectStatus.CANCELLED, ProjectStatus.IN_PROGRESS)),            () -> assertFalse(policy.canTransition(ProjectStatus.DELIVERED, ProjectStatus.PENDING)),            () -> assertFalse(policy.canTransition(ProjectStatus.PENDING, ProjectStatus.FINISHED))        );    }}